// ONCORA 6.0: bilingual, deterministic daily messages. No AI or therapeutic claims.
const dailyMessages=[
['Du musst heute nicht alles schaffen. Der nächste Schritt genügt.','You do not have to do everything today. The next step is enough.'],
['Auch Pausen gehören zu deinem Weg.','Rest is part of your journey, too.'],
['Du darfst Hilfe annehmen. Niemand muss alles allein tragen.','You are allowed to accept help. Nobody has to carry everything alone.'],
['Heute ist Platz für das, was du gerade fühlst.','There is room for whatever you feel today.'],
['Kleine Schritte verdienen genauso viel Anerkennung.','Small steps deserve recognition, too.'],
['Du bist mehr als eine Diagnose.','You are more than a diagnosis.'],
['Es ist in Ordnung, heute langsamer zu machen.','It is okay to slow down today.'],
['Du musst nicht jeden Tag mutig sein.','You do not have to feel brave every day.'],
['Manchmal ist Zuhören schon eine große Hilfe.','Sometimes being heard is a great help.'],
['Auch ein schwieriger Tag darf mit Freundlichkeit beginnen.','Even a difficult day can begin with kindness.'],
['Eine Frage zu stellen kann der Anfang von Klarheit sein.','Asking one question can be a beginning of clarity.'],
['Dein Tempo ist heute das richtige Tempo.','Your pace is the right pace for today.'],
['Es darf gleichzeitig Hoffnung und Unsicherheit geben.','Hope and uncertainty can exist together.'],
['Heute darfst du dir selbst Geduld schenken.','Today you can offer yourself patience.'],
['Nicht alles muss heute eine Antwort haben.','Not everything needs an answer today.'],
['Du darfst schlechte Tage haben, ohne dich zu erklären.','You can have hard days without needing to explain.'],
['Was dich beschäftigt, verdient Aufmerksamkeit.','What is on your mind deserves attention.'],
['Du bist mit deinen Fragen willkommen.','Your questions are welcome here.'],
['Ein stiller Moment kann schon guttun.','A quiet moment can be enough.'],
['Du darfst heute freundlich mit dir sein.','You can be gentle with yourself today.'],
['Manche Wege gehen sich leichter mit Begleitung.','Some paths feel easier with company.'],
['Heute zählt nicht die Geschwindigkeit.','Today is not about speed.'],
['Du musst nicht positiv sein, um Unterstützung zu verdienen.','You do not have to be positive to deserve support.'],
['Es ist okay, wenn dein Tag anders läuft als geplant.','It is okay if today goes differently than planned.'],
['Auch Fragen ohne einfache Antworten dürfen Raum haben.','Questions without easy answers deserve space, too.'],
['Deine Gefühle müssen nicht geordnet sein.','Your feelings do not have to be tidy.'],
['Du darfst dich auf das konzentrieren, was heute möglich ist.','You can focus on what is possible today.'],
['Jeder Tag darf eine andere Form von Stärke haben.','Strength can look different every day.'],
['Du darfst Unterstützung suchen, so oft du sie brauchst.','You can ask for support as often as you need.'],
['Heute darf Einfachheit genügen.','Today, simple is enough.'],
['Auch Unsicherheit gehört zur menschlichen Erfahrung.','Uncertainty is part of being human, too.']
];
function dayOfYearIndex(){const d=new Date(),mid=new Date(d.getFullYear(),d.getMonth(),d.getDate());return Math.floor(mid.getTime()/86400000)%dailyMessages.length}
let chosenQuoteOffset=0;
function activeQuoteIndex(){return (dayOfYearIndex()+chosenQuoteOffset+dailyMessages.length)%dailyMessages.length}
function dailyMessage(){return dailyMessages[activeQuoteIndex()][lang==='de'?0:1]}
let soundEnabled=localStorage.getItem('oncora-lumi-sound') !== 'off';
let lumiAudioContext;
function playLumiChime(){
 if(!soundEnabled)return;
 try{
  const AudioCtx=window.AudioContext||window.webkitAudioContext;
  if(!AudioCtx)return;
  if(!lumiAudioContext)lumiAudioContext=new AudioCtx();
  if(lumiAudioContext.state==='suspended')lumiAudioContext.resume().catch(()=>{});
  const now=lumiAudioContext.currentTime;
  [523.25,659.25,783.99,1046.50].forEach((frequency,i)=>{
   const oscillator=lumiAudioContext.createOscillator();
   const gain=lumiAudioContext.createGain();
   oscillator.type='sine';oscillator.frequency.value=frequency;
   const start=now+i*.085;
   gain.gain.setValueAtTime(.0001,start);
   gain.gain.exponentialRampToValueAtTime(.045,start+.04);
   gain.gain.exponentialRampToValueAtTime(.0001,start+.55);
   oscillator.connect(gain);gain.connect(lumiAudioContext.destination);
   oscillator.start(start);oscillator.stop(start+.58);
  });
 }catch(e){console.warn('Audio unavailable',e)}
}
