function lumiFigure(){return `<svg class="lumi-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 390 420" role="img" aria-label="${lang==='de'?'LUMI, animierter digitaler Begleiter':'LUMI, animated digital companion'}"><defs><radialGradient id="lumiHalo"><stop stop-color="#98ead8" stop-opacity=".35"/><stop offset=".65" stop-color="#58b9ac" stop-opacity=".11"/><stop offset="1" stop-color="#58b9ac" stop-opacity="0"/></radialGradient><linearGradient id="lumiBody" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#e0fff3" stop-opacity=".88"/><stop offset=".5" stop-color="#79d8cc" stop-opacity=".35"/><stop offset="1" stop-color="#e4e7ff" stop-opacity=".75"/></linearGradient><linearGradient id="lumiStroke" x1="0" x2="1"><stop stop-color="#7cf4df" stop-opacity=".35"/><stop offset=".5" stop-color="#e7fffb" stop-opacity=".9"/><stop offset="1" stop-color="#79edee" stop-opacity=".4"/></linearGradient><filter id="lumiGlow"><feGaussianBlur stdDeviation="4"/></filter></defs><circle cx="195" cy="195" r="165" fill="url(#lumiHalo)"/><g class="lumi-rings" fill="none" stroke="#b5fff1" stroke-width="1" opacity=".38"><ellipse cx="195" cy="230" rx="147" ry="35"/><ellipse cx="195" cy="230" rx="121" ry="24"/><path d="M30 230H359M195 53V375" stroke-dasharray="4 12"/></g><g class="lumi-floating"><path d="M97 352c3-51 27-70 61-83l14-23h48l14 23c34 13 58 32 61 83" fill="url(#lumiBody)" fill-opacity=".14" stroke="url(#lumiStroke)" stroke-width="2"/><path d="M162 266c12 19 26 28 34 28s23-9 35-28M120 313c25 14 46 20 76 20s51-6 76-20" stroke="#b3fff4" stroke-opacity=".55" fill="none"/><path d="M131 146c-3-51 23-89 65-92 42 3 68 41 65 92l-6 44c-5 45-31 74-59 74s-54-29-59-74z" fill="url(#lumiBody)" fill-opacity=".22" stroke="url(#lumiStroke)" stroke-width="2.2"/><path d="M135 137q17-73 60-70 52 3 61 70M147 176q5 56 48 77 43-21 48-77" fill="none" stroke="#e9fffb" stroke-opacity=".38"/><path d="M152 164q12-8 28-1m29 0q16-7 28 1" fill="none" stroke="#a9fff1" stroke-width="3.5" stroke-linecap="round"/><circle cx="170" cy="164" r="2.5" fill="#f4fffc"/><circle cx="221" cy="164" r="2.5" fill="#f4fffc"/><path d="M195 174l-4 20h8m-18 18q15 12 30 0" stroke="#d6fffa" stroke-opacity=".7" fill="none" stroke-linecap="round" stroke-width="2"/><g class="lumi-mesh" stroke="#d2fff8" stroke-opacity=".22" stroke-width=".8"><path d="M133 122q63 40 126 0M133 145q63 26 126 0M136 181q59 25 119 0M148 220q47 16 96 0M160 85l-10 137M182 72l-7 177M206 72l7 177M229 85l10 137" fill="none"/></g></g><g class="lumi-particles" fill="#cbfff6"><circle cx="72" cy="130" r="2"/><circle cx="311" cy="106" r="3"/><circle cx="322" cy="280" r="2"/><circle cx="98" cy="283" r="2.4"/><circle cx="274" cy="51" r="1.7"/></g><path d="M112 376h166" stroke="#99f7e6" stroke-opacity=".65" stroke-width="2"/><text x="195" y="403" fill="#c2f6e9" font-family="Arial,sans-serif" font-size="11" letter-spacing="5" text-anchor="middle">L U M I</text></svg>`}
function lumiHero(){return `<section class="lumi-hero" aria-label="${lang==='de'?'Begrüßung durch LUMI':'Greeting from LUMI'}"><div class="lumi-hero-copy"><div class="lumi-kicker"><span class="lumi-status-dot"></span>${lang==='de'?'DEIN DIGITALER BEGLEITER':'YOUR DIGITAL COMPANION'} <span class="lumi-version">ONCORA 6.0</span></div><div class="lumi-small-title">${lang==='de'?'Schön, dass du hier bist.':'Good to have you here.'}</div><h1>${lang==='de'?'Heute ist dein Tag. In deinem Tempo.':'Today is yours. At your own pace.'}</h1><p>${lang==='de'?'LUMI begrüßt dich, begleitet dich durch deine Übersicht und erinnert dich daran, dass du nicht alles auf einmal schaffen musst.':'LUMI welcomes you, guides you through your dashboard and reminds you that you do not have to do everything at once.'}</p><div class="lumi-hero-actions"><button class="btn lumi-primary" data-new="symptoms">✦ ${lang==='de'?'Wie geht es mir heute?':'How do I feel today?'}</button><button class="lumi-secondary" data-go="plan">${lang==='de'?'Meinen Tag ansehen':'View my day'} ↗</button></div></div><div class="lumi-figure-zone"><button class="lumi-figure-button" id="lumi-interact" aria-label="${lang==='de'?'LUMI begrüßen':'Greet LUMI'}" title="${lang==='de'?'LUMI antippen':'Tap LUMI'}">${lumiFigure()}</button><div class="lumi-dialog" id="lumi-dialog" role="status">${esc(dailyMessage())}</div><span class="lumi-caption">✧ ${lang==='de'?'LUMI antippen · Spruch wechseln':'Tap LUMI · change quote'}</span></div></section><section class="daily-quote"><div class="quote-sun" aria-hidden="true">✳</div><div class="quote-content"><div class="quote-eyebrow">${lang==='de'?'✦ DEIN GEDANKE DES TAGES':'✦ YOUR THOUGHT FOR TODAY'} <span class="quote-date">${new Date().toLocaleDateString(lang==='de'?'de-DE':'en-US',{day:'numeric',month:'long'})}</span></div><blockquote id="daily-quote-text" aria-live="polite">„${esc(dailyMessage())}“</blockquote><div class="quote-foot">${lang==='de'?'LUMI antippen: neuer Gedanke und sanfter Klang.':'Tap LUMI for another thought and a gentle chime.'}</div></div><button class="quote-sound" id="toggle-lumi-sound" aria-pressed="${soundEnabled}" aria-label="${lang==='de'?(soundEnabled?'Ton ausschalten':'Ton einschalten'):(soundEnabled?'Mute sound':'Enable sound')}" title="${lang==='de'?(soundEnabled?'Ton ausschalten':'Ton einschalten'):(soundEnabled?'Mute sound':'Enable sound')}">${soundEnabled?'♫':'♪̸'}</button><button class="quote-copy" id="copy-quote" title="${lang==='de'?'Gedanken kopieren':'Copy thought'}" aria-label="${lang==='de'?'Gedanken des Tages kopieren':'Copy today’s thought'}">↗</button></section>`}

const topics=[['Brustkrebs','Breast cancer','Entsteht in Zellen des Brustgewebes. Untersuchung und Behandlung hängen von der genauen Tumorart und dem Stadium ab.','Cancer arising in breast tissue. Examinations and treatment depend on subtype and stage.'],['Lungenkrebs','Lung cancer','Unterschiedliche Tumorarten der Lunge. Diagnostik kann Bildgebung, Gewebeprobe und molekulare Tests umfassen.','Different lung cancer types. Tests may include imaging, biopsy and molecular analysis.'],['Darmkrebs','Colorectal cancer','Betrifft Dickdarm oder Enddarm. Die Therapie kann Operation, Medikamente und weitere Maßnahmen umfassen.','Affects the colon or rectum. Treatment may involve surgery, medicines and other approaches.'],['Prostatakrebs','Prostate cancer','Tumor der Prostata. Behandlung richtet sich unter anderem nach Ausbreitung, Beschwerden und individuellen Faktoren.','Cancer of the prostate. Management depends on spread, symptoms and individual factors.'],['Bauchspeicheldrüsenkrebs','Pancreatic cancer','Erkrankung der Bauchspeicheldrüse. Fachärztliche Diagnostik ist für Therapieentscheidungen entscheidend.','Cancer of the pancreas. Specialist diagnostic work-up guides treatment decisions.'],['Gallenblasenkrebs','Gallbladder cancer','Seltene Krebserkrankung der Gallenblase. Therapieplanung erfolgt abhängig von Ausbreitung und Allgemeinzustand.','Rare cancer of the gallbladder. Treatment planning depends on stage and overall health.'],['Gallengangskrebs','Bile duct cancer','Auch Cholangiokarzinom genannt. Die genaue Lage des Tumors kann die Behandlung beeinflussen.','Also called cholangiocarcinoma. Tumor location can influence treatment.'],['Leberkrebs','Liver cancer','Es gibt verschiedene Lebertumoren; wichtig ist die Unterscheidung zwischen primären Tumoren und Metastasen.','Different liver tumors exist; distinguishing primary cancer from metastases matters.'],['Magenkrebs','Stomach cancer','Bösartige Erkrankung des Magens. Die genaue Diagnostik erfolgt durch ärztliche Untersuchungen.','Malignancy of the stomach. Diagnosis requires medical assessment.'],['Nierenkrebs','Kidney cancer','Entsteht im Nierengewebe; Behandlung hängt von Typ, Stadium und weiteren Faktoren ab.','Arises in kidney tissue; treatment depends on type, stage and other factors.'],['Blasenkrebs','Bladder cancer','Tumorerkrankung der Harnblase; Stadien und Befallstiefe sind für die Behandlung wichtig.','Cancer of the urinary bladder; stage and depth of invasion guide care.'],['Eierstockkrebs','Ovarian cancer','Unterschiedliche Erkrankungen des Eierstockgewebes; individuelle Diagnostik und Behandlungsplanung sind wichtig.','Various ovarian cancers; individual diagnostic work-up and care planning matter.'],['Gebärmutterhalskrebs','Cervical cancer','Krebserkrankung am Gebärmutterhals. Die Behandlung orientiert sich am Stadium.','Cancer of the cervix. Treatment depends on stage.'],['Hirntumoren','Brain tumors','Unterschiedliche Tumoren des Gehirns oder seiner Umgebung, die sehr verschieden behandelt werden.','Different types of tumors of the brain and surrounding tissues require different care.'],['Leukämie','Leukemia','Gruppe von Krebserkrankungen des blutbildenden Systems; es gibt akute und chronische Formen.','A group of blood-forming tissue cancers, including acute and chronic forms.'],['Lymphome','Lymphoma','Krebserkrankungen des lymphatischen Systems mit zahlreichen Untertypen.','Cancers of the lymphatic system with numerous subtypes.'],['Hautkrebs','Skin cancer','Umfasst verschiedene Krebsarten wie Melanome und nicht-melanozytäre Hauttumoren.','Includes melanoma and non-melanoma skin cancers.'],['Chemotherapie','Chemotherapy','Medikamentöse Behandlung, die das Wachstum von Krebszellen hemmen soll. Art und Nebenwirkungen unterscheiden sich.','Drug treatment intended to inhibit cancer cell growth. Regimens and side effects vary.'],['Immuntherapie','Immunotherapy','Behandlungsverfahren, die das Immunsystem gegen Krebs unterstützen können. Bestimmte Nebenwirkungen können dringend sein.','Treatments that engage the immune system against cancer. Some adverse effects require urgent assessment.'],['Strahlentherapie','Radiotherapy','Gezielte Behandlung mit ionisierender Strahlung, deren Einsatz von der Erkrankung abhängt.','Targeted treatment using radiation; its role depends on the condition.'],['Operation','Surgery','Chirurgische Entfernung von Tumorgewebe kann abhängig von Erkrankung und Stadium eingesetzt werden.','Surgical removal of tumor tissue may be an option depending on type and stage.'],['Palliativmedizin','Palliative care','Ziel ist die Linderung belastender Symptome und eine bessere Lebensqualität – auch begleitend zu anderen Therapien.','Aims to ease symptoms and support quality of life, sometimes alongside other treatments.'],['Metastase','Metastasis','Absiedlung von Krebszellen an anderer Stelle des Körpers.','Spread of cancer cells to another site in the body.'],['Rezidiv','Recurrence','Erneutes Auftreten einer Erkrankung nach einer Phase ohne nachweisbare Erkrankung.','Return of disease after a period without detectable disease.'],['Biopsie','Biopsy','Entnahme von Gewebe zur mikroskopischen Untersuchung.','Taking a tissue sample for examination.'],['Tumormarker','Tumor marker','Messwert, der in manchen Situationen bei Verlaufskontrollen helfen kann; allein oft nicht beweisend.','A measured marker that may help monitor some cancers; usually not conclusive by itself.'],['Tumorboard','Multidisciplinary tumor board','Besprechung eines Falls durch Fachleute verschiedener Disziplinen.','Case discussion by specialists from different disciplines.'],['Nachsorge','Follow-up care','Kontrollen und Unterstützung nach einer Behandlung; Intervalle hängen von der Erkrankung ab.','Check-ups and support after treatment; schedules depend on disease.']];

